INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','trade-case-workspace','Trade Case Workspace','Each shipment or trade transaction becomes a structured case that holds its documents, extracted data, review notes and decisions.','','{"capabilities":"Case timeline\nLinked documents\nReviewer notes"}','Published','In Development',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','document-intelligence','Document Intelligence','Identifies common trade document types and extracts available fields for human review — invoices, packing lists, transport documents.','','{"capabilities":"Type identification\nField extraction\nConfidence flags"}','Published','In Development',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','cross-document-comparison','Cross-Document Comparison','Compares values across documents in a case and highlights mismatches such as quantities, weights, parties or totals.','','{"capabilities":"Mismatch highlighting\nSide-by-side evidence"}','Published','In Development',2,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','review-approval-workflow','Review & Approval Workflow','Routes flagged items to the right person and records who reviewed what, when and why — an evidence trail, not a black box.','','{"capabilities":"Assignments\nAudit trail\nHuman sign-off"}','Published','Planned',3,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','workflow-automation','Workflow Automation','Automates repetitive follow-ups, notifications and data hand-offs between your inbox, spreadsheets and business systems.','','{"capabilities":"Email triggers\nScheduled follow-ups\nHand-offs"}','Published','Custom Build',4,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','operational-reporting','Operational Reporting','Summaries of case status, open exceptions and turnaround — built from your own operational data.','','{"capabilities":"Exception overview\nTurnaround views"}','Published','Planned',5,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('platform','integrations','Integrations','Connections to email, spreadsheets, CRMs and accounting tools are scoped per engagement. No pre-built government or customs integrations are offered.','','{"capabilities":"Email\nSpreadsheets\nCRM / accounting (scoped)"}','Published','Custom Build',6,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('automations','inquiry-triage-automation','Inquiry Triage & Routing','Captures new inquiries, classifies them by topic and business type, and routes them to the right team with a structured summary.','Email & Inquiry Automation','{"problem":"Inquiries arrive across inboxes and forms, and response quality depends on whoever sees them first.","workflow":"New inquiry → classification → internal routing with context → acknowledgement to the sender.","integrations":"Email (IMAP/SMTP)\nCRM\nTeam chat","deployment":"Managed environment"}','Published','In Development',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('automations','shipment-follow-up-automation','Shipment Follow-Up Assistant','Tracks open document and status requests and prepares polite, structured follow-up messages for your team to approve and send.','Shipment Follow-Up','{"problem":"Chasing document and status updates from suppliers, forwarders and customers is repetitive and easy to miss.","workflow":"Open request detected → follow-up prepared → human approval → sent and logged on the case.","integrations":"Email (IMAP/SMTP)\nShared inbox\nCase tracker","deployment":"Managed environment"}','Published','In Development',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('automations','document-intake-workflow','Trade Document Intake & Structuring','Identifies document types, extracts available fields and organizes shipment information into a structured case view.','Document Processing','{"problem":"Commercial invoices, packing lists and transport documents arrive as attachments that someone must read and re-key.","workflow":"Documents received → type detection → field extraction → structured case → exception flags for reviewers.","integrations":"Email (IMAP/SMTP)\nShared drives\nCustom API","deployment":"Managed or client-owned environment"}','Published','In Development',2,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('automations','invoice-packing-list-reconciliation','Invoice & Packing List Reconciliation','Compares key values across document sets, highlights missing or conflicting entries and produces an evidence-backed review workpaper.','Invoice Reconciliation','{"problem":"Cross-checking invoices against packing lists and transport documents line by line is slow and error-prone.","workflow":"Document set linked → cross-document comparison → mismatches flagged with references → human review.","integrations":"ERP\nEmail (IMAP/SMTP)\nCustom API","deployment":"Managed or client-owned environment"}','Published','In Development',3,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('automations','reporting-automation','Operations Reporting Automation','Compiles recurring operational reports from approved sources on a schedule your team defines.','Business Reporting','{"problem":"Operational reporting is assembled by hand from exports, so leadership sees stale numbers.","workflow":"Scheduled run → data compiled from approved sources → report prepared → distribution list notified.","integrations":"ERP\nSpreadsheets\nEmail (IMAP/SMTP)","deployment":"Managed environment"}','Published','Planned',4,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('automations','custom-ai-agent','Custom AI Agent for Your Workflow','A purpose-built agent designed with you around your documents, systems and approval rules — scoped, built and tested with your team.','Custom AI Agents','{"problem":"Some workflows are unique to your business and no off-the-shelf automation fits them.","workflow":"Requirement intake → discovery and scope → build and test → deployment with human approval points.","integrations":"Agreed during scoping","deployment":"Managed or client-owned environment"}','Published','Custom Build',5,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('services','operations-assessment','Operations Assessment','A structured review of how documents, data and decisions move through your trade operations today.','','{"deliverables":"Workflow map\nBottleneck findings\nPrioritized opportunities"}','Published','Available',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('services','workflow-automation-build','Workflow Automation Build','Design and build of automations for follow-ups, notifications, intake and data hand-offs.','','{"deliverables":"Scoped specification\nBuilt automation\nHandover documentation"}','Published','Custom Build',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('services','custom-ai-agents','Custom AI Agents','Task-specific assistants that draft, classify or summarize — always with human review before anything is sent or approved.','','{"deliverables":"Agent design\nReview controls\nPilot evaluation"}','Published','Custom Build',2,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('services','systems-integration','Systems Integration','Connecting email, spreadsheets, CRM and accounting tools you already use, scoped per engagement.','','{"deliverables":"Integration plan\nConnectors\nMonitoring guidance"}','Published','Custom Build',3,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('services','pilot-ongoing-support','Pilot & Ongoing Support','A measured pilot on real work, followed by optional support and iteration as your operation changes.','','{"deliverables":"Pilot plan\nSuccess measures\nSupport arrangement"}','Published','Available',4,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('solutions','importers','Importers','Businesses receiving goods from international suppliers.','','{"challenges":"Supplier documents arrive in different formats\nValues that don''t match the purchase order\nChasing missing paperwork","benefits":"Organize supplier documents per shipment\nFlag mismatches before goods arrive\nAutomate document follow-ups"}','Published','Planned',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('solutions','exporters','Exporters','Manufacturers and traders shipping to overseas buyers.','','{"challenges":"Preparing consistent document sets\nBuyer queries across email threads\nManual re-keying of order data","benefits":"Check document sets for consistency\nStructure buyer communication per order\nReduce re-keying with extraction"}','Published','Planned',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('solutions','freight-forwarders','Freight Forwarders','Forwarders coordinating many shipments for many clients.','','{"challenges":"High document volume per shipment\nStatus requests from every client\nExceptions buried in inboxes","benefits":"Case-based shipment workspaces\nAutomated status follow-ups\nVisible exception queues"}','Published','Planned',2,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('solutions','logistics-operators','Logistics Operators','Warehousing, transport and 3PL teams.','','{"challenges":"Hand-offs between teams\nInconsistent operational data\nReporting assembled by hand","benefits":"Structured hand-off workflows\nData checks at intake\nReporting from operational records"}','Published','Planned',3,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('solutions','trading-companies','Trading Companies','Firms buying and selling across borders.','','{"challenges":"Many counterparties, many formats\nInvoice and packing list reconciliation\nLimited visibility across deals","benefits":"Reconcile commercial documents\nTrack counterparties per case\nOne view of open exceptions"}','Published','Planned',4,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('industries','textiles-apparel','Textiles & Apparel','Multi-supplier orders, size and quantity breakdowns, frequent packing list variations.','','{}','Published','Planned',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('industries','agriculture-food','Agriculture & Food','Perishable timelines, certificates tied to specific consignments, seasonal volume spikes.','','{}','Published','Planned',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('industries','industrial-machinery','Industrial & Machinery','High-value shipments, detailed specifications and serial-numbered items.','','{}','Published','Planned',2,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('industries','consumer-goods','Consumer Goods','Large SKU counts, repeat shipments and frequent buyer communication.','','{}','Published','Planned',3,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('industries','chemicals-materials','Chemicals & Materials','Specification-heavy documentation where consistency across documents matters.','','{}','Published','Planned',4,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('industries','electronics-components','Electronics & Components','Part-number accuracy, multiple consignees and tight delivery windows.','','{}','Published','Planned',5,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','is-aether-trade-available-today','Is AETHER-TRADE available today?','Parts of the platform are in development. Consulting, assessments and custom automation builds are available now. Every capability on this site carries a status label so you know exactly what exists.','','{}','Published','Planned',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','do-you-handle-customs-clearance','Do you handle customs clearance?','No. AETHER-TRADE is operations software and automation. We do not provide customs clearance, brokerage or legal advice, and we do not integrate with government systems.','','{}','Published','Planned',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','does-ai-make-decisions-on-our-shipments','Does AI make decisions on our shipments?','No. AI assists with identifying, extracting and comparing information. A person reviews and approves every outcome.','','{}','Published','Planned',2,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','can-we-upload-documents-through-the-website','Can we upload documents through the website?','No. For your security we never accept trade documents through public forms. Documents are only shared within an agreed engagement.','','{}','Published','Planned',3,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','do-we-need-to-replace-our-existing-systems','Do we need to replace our existing systems?','No. We work around the email, spreadsheets and tools you already use and connect to them where it makes sense.','','{}','Published','Planned',4,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','how-does-an-engagement-start','How does an engagement start?','With a conversation and a short operations assessment. From there we scope one workflow and pilot it before anything larger.','','{}','Published','Planned',5,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('faqs','what-size-of-business-do-you-work-with','What size of business do you work with?','Importers, exporters, forwarders and logistics teams that handle enough shipments for manual work to become a real cost.','','{}','Published','Planned',6,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('insights','why-trade-documents-dont-match','Why trade documents so often don''t match','A look at where quantity, weight and value mismatches usually come from — and how to catch them earlier.','Operations','{"author":"","tags":""}','Draft','Planned',0,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('insights','case-based-shipment-management','Thinking in cases, not inboxes','Why organizing each shipment as a structured case changes how teams review, hand off and resolve issues.','Workflows','{"author":"","tags":""}','Draft','Planned',1,false);
INSERT INTO public.content_records(module,slug,title,body,category,fields,publication,availability,position,noindex) VALUES ('insights','human-review-in-ai-workflows','Where human review belongs in AI workflows','Practical patterns for keeping people in control when automation handles the repetitive parts.','AI in practice','{"author":"","tags":""}','Draft','Planned',2,false);
